def shell(title,body,theme):
 return f'''<!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f6f3eb"><meta name="description" content="{title} — mustaqil interaktiv dizayn namunasi."><title>{title}</title><link rel="icon" href="mark.svg" type="image/svg+xml"><link rel="preload" href="fonts/instrument-1.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="fonts/instrument-5.woff2" as="font" type="font/woff2" crossorigin><script>document.documentElement.classList.add('font-loading')</script><link rel="stylesheet" href="style.css?v=2"><script type="module" src="app.js?v=2"></script></head><body><a class="skip" href="#main">Asosiy mazmunga o‘tish</a>{body}</body></html>'''

def nav(brand,links):
 a=''.join(f'<a href="{url}">{label}</a>' for url,label in links)
 return f'<header class="header wrap"><a class="wordmark" href="#main" aria-label="{brand} bosh sahifasi">{brand}<span>.</span></a><nav class="nav" aria-label="Asosiy navigatsiya">{a}</nav><details class="mobile-nav"><summary>Menyu <span aria-hidden="true">+</span></summary><nav aria-label="Mobil navigatsiya">{a}</nav></details></header>'

def build():
 samar=nav('samar',[('#manzillar','Manzillar'),('#reja','Kun rejasi (<span class="nav-count">0</span>)'),('#tayyorgarlik','Tayyorgarlik')])
 samar+='''<main id="main"><section class="wrap travel-hero"><div class="hero-copy"><p class="eyebrow">SAMARQAND / SHAXSIY SAYOHAT REJASI</p><h1>Samarqand.<br><em>Shoshmasdan.</em></h1><p class="lead">Moviy koshinlar, keng maydonlar va asrlik hikoyalar. Uch manzilni kashf eting, kuningizni o‘zingiz rejalashtiring.</p><a class="button" href="#manzillar">Manzillarni kashf etish <span aria-hidden="true">↗</span></a><p class="hero-foot">03 MANZIL · MUSTAQIL SAYR · SIZNING KETMA-KETLIGINGIZ</p></div><figure class="hero-photo"><img src="images/registan.jpg" width="1600" height="1200" alt="Samarqanddagi Registon maydonining uch madrasali ko‘rinishi" fetchpriority="high"><figcaption><span>01 / Registon maydoni</span><a href="CREDITS.md">Surat: Euyasik ↗</a></figcaption></figure></section><section id="manzillar" class="section wrap"><div class="section-head"><div><p class="eyebrow">TANLANGAN MANZILLAR</p><h2>Har biri uchun<br>vaqt ajrating.</h2></div><p>Joyning hikoyasini o‘qing va rejangizga qo‘shing. Ketma-ketlik va boshlanish vaqtini keyingi bo‘limda o‘zgartiring.</p></div><div class="destinations">'''
 for id,name,image,tag,intro,minutes in [('registan','Registon maydoni','registan.jpg','ME’MORCHILIK','Uch madrasa. Bitta ulkan taassurot.',75),('shohi-zinda','Shohi Zinda','shohi-zinda.jpg','NAQSH VA XOTIRA','Moviy rangning ming xil ohangi.',60),('guri-amir','Go‘ri Amir','guri-amir.jpg','TEMURIYLAR MEROSI','Samarqand osmonidagi moviy gumbaz.',60)]:
  samar+=f'<article class="destination"><button class="place-photo" data-detail="{id}" aria-label="{name} haqida batafsil"><img src="images/{image}" width="800" height="640" loading="lazy" alt="{name} me’moriy ko‘rinishi"></button><div class="place-meta"><span>{tag}</span><span>~ {minutes} DAQIQA</span></div><h3>{name}</h3><p>{intro}</p><div class="place-actions"><button class="button secondary" data-toggle="{id}" aria-pressed="false">Rejaga qo‘shish +</button><button class="text-link" style="background:none;padding:0;border:0;border-bottom:1px solid var(--ink)" data-detail="{id}" aria-label="{name}: hikoyasini o‘qish">Hikoyasini o‘qish ↗</button></div></article>'
 samar+='''</div><p id="live-status" class="live" role="status" aria-live="polite"></p></section><section class="planner-band" id="reja"><div class="wrap planner"><div class="planner-intro"><p class="eyebrow">SIZNING KUNINGIZ</p><h2>Yo‘nalish tayyor.<br>Endi <em>siz tanlang.</em></h2><p>Manzillarni qo‘shing, tartibini o‘zgartiring va rejangizni matn fayli qilib oling. Shaxsiy ma’lumot yoki ro‘yxatdan o‘tish kerak emas.</p><div class="notice">Vaqtlar — tashrif uchun taklif. Manzillar orasiga shartli 20 daqiqa qo‘shiladi. Haqiqiy yo‘l va tashrif vaqtini joyida tekshiring.</div></div><div class="planner-box"><div class="planner-toolbar"><div><h3 id="plan-heading" tabindex="-1">Kun rejangiz</h3><label for="start-time">Boshlanish vaqti<input id="start-time" type="time" value="09:00" required></label></div><span class="count" id="plan-count" aria-label="Tanlangan manzillar soni">0</span></div><div id="plan-empty"><strong>Qaysi manzildan boshlaymiz?</strong><p>Yuqoridagi manzillardan kamida bittasini qo‘shing.</p></div><ol id="plan-list"></ol><div class="planner-bottom"><p class="small" id="plan-duration">Manzillarni tanlang</p><button id="download" class="button" disabled>Rejani yuklab olish <span aria-hidden="true">↓</span></button><p class="small" id="storage-note">Reja shu brauzerda saqlanadi. Bu chipta yoki bron emas.</p></div></div></div></section><section id="tayyorgarlik" class="section wrap"><div class="guide"><div><p class="eyebrow">YO‘LGA CHIQISHDAN OLDIN</p><h2>Kichik tayyorgarlik.<br>Yaxshiroq sayr.</h2><p>Manzillar haqida rasmiy ma’lumotlar Uzbekistan Travel’dan tekshirildi. Joriy narx va ochilish vaqti bu yerda taxmin qilinmaydi.</p><a class="text-link" href="https://uzbekistan.travel/en/i/samarkand/">Rasmiy shahar qo‘llanmasi ↗</a></div><div><details><summary>Chipta va ochilish vaqti</summary><p>Tashrif kuni rasmiy sahifa yoki manzil kassasidan tekshiring. Bu saytdagi reja kirish huquqini bermaydi.</p></details><details><summary>Kiyim va ziyorat odobi</summary><p>Diniy maskanlarda hurmatli kiyim va sokinlik muhim. Joydagi suratga olish va kirish ko‘rsatmalariga rioya qiling.</p></details><details><summary>Sayrni o‘zingizga moslang</summary><p>Qulay oyoq kiyim, suv va ob-havoga mos kiyim oling. Rejadagi vaqtlar taxminiy: dam olish uchun qo‘shimcha vaqt ajrating.</p></details></div></div></section></main><footer class="footer wrap"><div><a class="wordmark" href="#main">samar<span>.</span></a><p>Mustaqil sayohat rejalashtirish namunasi. Turagentlik, rasmiy portal yoki bron xizmati emas.</p></div><nav aria-label="Qo‘shimcha havolalar"><a href="https://azizbeksafarov.github.io/design/">Dizaynlar</a><a href="https://azizbeksafarov.github.io/design/samar/">AI konteksti</a><a href="CREDITS.md">Suratlar va manbalar</a></nav></footer><dialog id="detail" aria-labelledby="detail-title"><div class="dialog-head"><h2 id="detail-title">Manzil haqida</h2><button class="close" data-close aria-label="Yopish">×</button></div><div class="dialog-content"><img id="detail-image" class="detail-image" alt=""><p id="detail-text"></p><p class="notice" id="detail-note"></p><div class="dialog-links"><a id="detail-source" class="text-link" href="https://uzbekistan.travel/">Rasmiy manba ↗</a><a id="detail-map" class="text-link" href="https://maps.google.com/">Xaritada ko‘rish ↗</a></div></div></dialog>'''
